"""One hundred individually authored ruin proposals; design-only output."""
from encounter_helpers import choice as C, event, write

ROWS = []

def add(n, title, context, place, axis, deps, refs, first, second, followup,
        decline="記下位置後離開", decline_outcome="保留位置線索，本次不取得物品，也不處理現場問題。"):
    dependencies = set(["item_ownership", "exploration"] + deps.split(","))
    held_ids = set(first["required_items"] + second["required_items"])
    if "content_flashlight" in held_ids:
        dependencies.update(["lighting", "electronics"])
    ROWS.append(event(f"ruin_{n:03d}", "ruins", title, context, ["ruins", place], axis,
        [first, second, C(decline, "不交出物品，不承接此處工作。", decline_outcome)],
        followup, sorted(dependencies), refs.split(",")))

